/* MerchBoard Studio offline cache — generated by build_pwa.py */
const CACHE = 'merchboard-imp2';
const FILES = ["./", "icons/icon-180.png", "icons/icon-192.png", "icons/icon-512.png", "index.html", "js/ai.js", "js/core.js", "js/export.js", "js/jsx.js", "js/layout.js", "js/psd.js", "js/render.js", "js/ui.js", "js/vlib.js", "manifest.webmanifest", "style.css", "vendor/ag-psd.bundle.js", "vendor/jspdf.umd.min.js", "vendor/xlsx.full.min.js"];
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  e.respondWith(caches.match(e.request, { ignoreSearch: true }).then(hit => hit || fetch(e.request)));
});
